$ErrorActionPreference='Stop';$d=Join-Path $env:TEMP ('bc-knowledge-positive-'+[guid]::NewGuid().ToString('N'));try{& (Join-Path $PSScriptRoot 'New-SyntheticBCConsultantKnowledge.ps1') -Destination $d;$f=Join-Path $d 'bc-knowledge.json';$before=(Get-FileHash $f -Algorithm SHA256).Hash;$a=&(Join-Path $PSScriptRoot 'Test-BCConsultantKnowledge.ps1') -Path $d -Process finance -Role consultant -ProjectPhase implementation -TaskType setup;$b=&(Join-Path $PSScriptRoot 'Test-BCConsultantKnowledge.ps1') -Path $d -Process finance -Role consultant -ProjectPhase implementation -TaskType setup;$after=(Get-FileHash $f -Algorithm SHA256).Hash;if($a.count-ne1-or$b.count-ne1-or$before-ne$after){throw 'BC_KNOWLEDGE_QUERY_NOT_IDEMPOTENT'};Write-Output 'PASS: 19 Bereiche, 5 Playthroughs und deterministische Query.'}finally{if(Test-Path $d){Remove-Item $d -Recurse -Force}}
